<style>.testimony-member-grid{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(300px,.85fr);gap:18px}.testimony-submit form{display:grid;gap:14px}.testimony-submit label{display:grid;gap:7px;font-weight:750;font-size:.78rem}.testimony-submit input,.testimony-submit select,.testimony-submit textarea{width:100%;border:1px solid var(--line);border-radius:11px;background:var(--surface);color:var(--text);padding:11px}.testimony-submit small{color:var(--muted);font-weight:500}.testimony-safe{display:flex;align-items:center;gap:6px;border-radius:999px;padding:7px 10px;background:color-mix(in srgb,var(--action) 10%,var(--surface));color:var(--action);font-size:.7rem;font-weight:800}.testimony-profile-note{display:flex;align-items:center;gap:10px;color:var(--muted);font-size:.7rem;line-height:1.4}.testimony-profile-note img,.testimony-profile-note>span:first-child{display:grid;width:42px;height:42px;place-items:center;flex:0 0 auto;border-radius:50%;object-fit:cover;background:color-mix(in srgb,var(--action) 13%,var(--surface));color:var(--action);font-weight:850}.testimony-consent{grid-template-columns:auto 1fr!important;align-items:start;line-height:1.5}.testimony-consent input{width:auto;margin-top:3px}.testimony-history>div{display:grid;gap:10px}.testimony-history article{position:relative;display:grid;gap:8px;padding:16px;border:1px solid var(--line);border-radius:14px;background:var(--surface-muted)}.testimony-history h3,.testimony-history p{margin:0}.testimony-history p,.testimony-history small{color:var(--muted)}.testimony-status{justify-self:start;padding:5px 8px;border-radius:999px;background:var(--surface);font-size:.65rem;font-weight:850;text-transform:uppercase;letter-spacing:.07em}.status-published{color:var(--success)}.status-rejected,.status-withdrawn{color:var(--danger)}.testimony-history button{border:0;background:none;color:var(--danger);padding:0;font-weight:750}@media(max-width:880px){.testimony-member-grid{grid-template-columns:1fr}}</style></